namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokHistorieUzaverkyTab extends GContentBase {

        private ciziMena: boolean;
        private grid: JQuery<HTMLElement>;
        title: string;
        private ixpDen: string;

        onContentReady() {

            var that = this;

            this.setBreadcrumbs([{ caption: this.title,  defaultAction : true }]);

            Gordic.Isl.PokKniha.read({ ixp_den: that.ixpDen })
                .getData()
                .done(function (data) {

                    that.ciziMena = data.mena != 0

                    that.grid = $("<div>").appendTo(that.element)
                        .css("height", "100%")
                        .ggrid({
                            data: new Gordic.Isl.View(Gordic.Isl.PokKniha.historieUzaverek(rq => { return { filters: { ixp_den: that.ixpDen } } })),   // this.modelPolozky[0]   //zatim nemam zadna data, nastavim prazdne pole. V momente nacteni je nastavim pres options (metoda loadJsGrid)
                            renderMode: "auto",     // auto, all-at-once, paged-sync, paged-async
                            columnMode: "fit",      // fit, full
                            navigationMode: "row",  // row, cell
                            //scrollHelperTemplate: "{ac}",
                            //  searchColumns: ["ac"],
                            rowNumbers: false,
                            columns: that.createGridFormat()
                        });

                });
        }

        private createGridFormat(): Gordic.Data.GridFormat<Gordic.Hpl.Interface.GPokHistUzaverekDto> {

         
            var gridFormat = new Gordic.Data.GridFormat<Gordic.Hpl.Interface.GPokHistUzaverekDto>(); 

            gridFormat.addNumberColumn({ name: "por_cislo", caption: "jres:31302305", width: 50 });  //RC 31302305 : Poř. číslo
            gridFormat.addTextColumn({ name: "typ_uz_txt", caption: "jres:31302306", width: 80 }); //RC 31302306 : Typ uzávěrky
            if (this.ciziMena) {
                gridFormat.addCurrencyColumn({ name: "c_h_prijem", caption: "jres:31302307", width: 90 }); //RC 31302307 : Hot. příjem (CZK)
                gridFormat.addCurrencyColumn({ name: "c_h_vydej", caption: "jres:31302308", width: 90 }); //RC 31302308 : Hot. výdej (CZK)
                gridFormat.addCurrencyColumn({ name: "c_h_zustatek", caption: "jres:31302309", width: 90 }); //RC 31302309 : Hot. zůstatek (CZK)
                gridFormat.addCurrencyColumn({ name: "c_b_prijem", caption: "jres:31302310", width: 90 }); //RC 31302310 : Bezh. příjem (CZK)
                gridFormat.addCurrencyColumn({ name: "c_b_vydej", caption: "jres:31302311", width: 90 }); //RC 31302311 : Bezh. výdej (CZK)
                gridFormat.addCurrencyColumn({ name: "c_b_zustatek", caption: "jres:31302312", width: 90 }); //RC 31302312 : Bezh. zůstatek (CZK)
            }

            gridFormat.addCurrencyColumn({ name: "c_h_prijem_m", caption: "jres:31302307", width: 90 }); //RC 31302313 : Hot. příjem
            gridFormat.addCurrencyColumn({ name: "c_h_vydej_m", caption: "jres:31302308", width: 90 }); //RC 31302314 : Hot. výdej
            gridFormat.addCurrencyColumn({ name: "c_h_zustatek_m", caption: "jres:31302309", width: 90 }); //RC 31302315 : Hot. zůstatek
            gridFormat.addCurrencyColumn({ name: "c_b_prijem_m", caption: "jres:31302310", width: 90 }); //RC 31302316 : Bezh. příjem
            gridFormat.addCurrencyColumn({ name: "c_b_vydej_m", caption: "jres:31302311", width: 90 }); //RC 31302317 : Bezh. výdej
            gridFormat.addCurrencyColumn({ name: "c_b_zustatek_m", caption: "jres:31302312", width: 90 }); //RC 31302318 : Bezh. zůstatek

            gridFormat.addTextColumn({ name: "nazev_rf", caption: "jres:31302319", width: 100 });  //RC 31302319 : Změnu prov.
            gridFormat.addDateTimeColumn({ name: "dat_zmena", caption: "jres:31302320", width: 90 }); //RC 31302320 : Vytvořeno

            return gridFormat;

        }


    }
}




